// Concept of a Feature Flag in Trunk Based Development

function renderLogin() {
  // Even though the new UI isn't finished, the code is safely merged into 'main'!
  // We just hide it using a configuration variable.
  if (config.ENABLE_NEW_UI === true) {
    return <NewExperimentalLogin />;
  } else {
    return <OldStableLogin />;
  }
}
